import { Component, Input, Output, EventEmitter, OnChanges, SimpleChanges, OnInit } from '@angular/core';
import { Email } from '../../../../core/models/email.model';
import { EmailService } from '../../../../core/services/email.service';

@Component({
  selector: 'app-email-list',
  templateUrl: './email-list.component.html',
  styleUrls: ['./email-list.component.scss']
})
export class EmailListComponent implements OnInit, OnChanges {
  @Input() folder = 'inbox';
  @Output() emailSelected = new EventEmitter<Email>();

  emails: Email[] = [];
  filteredEmails: Email[] = [];
  selectedEmail: Email | null = null;
  searchQuery = '';
  isLoading = false;

  constructor(private emailService: EmailService) {}

  ngOnInit(): void {
    this.emailService.selectedEmail$.subscribe(email => {
      this.selectedEmail = email;
    });
    this.loadEmails();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['folder'] && !changes['folder'].firstChange) {
      this.searchQuery = '';
      this.loadEmails();
    }
  }

  loadEmails(): void {
    this.isLoading = true;
    this.emailService.getEmailsByFolder(this.folder).subscribe(emails => {
      this.emails = emails;
      this.filteredEmails = emails;
      this.isLoading = false;
      // Auto-select first email
      if (emails.length > 0) {
        this.selectEmail(emails[0]);
      } else {
        this.emailService.selectEmail(null as any);
      }
    });
  }

  onSearch(query: string): void {
    this.searchQuery = query;
    if (!query.trim()) {
      this.filteredEmails = this.emails;
      return;
    }
    const lower = query.toLowerCase();
    this.filteredEmails = this.emails.filter(e =>
      e.sender.toLowerCase().includes(lower) ||
      e.subject.toLowerCase().includes(lower) ||
      e.preview.toLowerCase().includes(lower)
    );
  }

  selectEmail(email: Email): void {
    this.emailService.selectEmail(email);
    this.emailSelected.emit(email);
  }

  toggleStar(email: Email): void {
    this.emailService.toggleStar(email);
  }

  trackById(_index: number, email: Email): string {
    return email.id;
  }

  get folderTitle(): string {
    const titles: Record<string, string> = {
      inbox: 'Inbox', sent: 'Sent', drafts: 'Drafts', trash: 'Trash'
    };
    return titles[this.folder] || this.folder;
  }

  get unreadCount(): number {
    return this.emails.filter(e => !e.isRead).length;
  }
}
<div class="email-list">
  <!-- Header -->
  <div class="email-list__header">
    <div class="email-list__title-row">
      <h2 class="email-list__title">{{ folderTitle }}</h2>
      <span class="email-list__unread-badge" *ngIf="unreadCount > 0">{{ unreadCount }} new</span>
    </div>

    <!-- Search -->
    <div class="email-list__search">
      <svg class="email-list__search-icon" width="16" height="16" viewBox="0 0 16 16" fill="none">
        <circle cx="7" cy="7" r="4.5" stroke="currentColor" stroke-width="1.5"/>
        <path d="M10.5 10.5L14 14" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
      </svg>
      <input
        type="text"
        class="email-list__search-input"
        placeholder="Search {{ folderTitle | lowercase }}..."
        [value]="searchQuery"
        (input)="onSearch($any($event.target).value)"
      />
      <button
        class="email-list__search-clear"
        *ngIf="searchQuery"
        (click)="onSearch('')">
        ×
      </button>
    </div>
  </div>

  <!-- Loading skeleton -->
  <div class="email-list__body" *ngIf="isLoading">
    <div class="email-list__skeleton" *ngFor="let i of [1,2,3,4,5]">
      <div class="skeleton-avatar"></div>
      <div class="skeleton-lines">
        <div class="skeleton-line skeleton-line--short"></div>
        <div class="skeleton-line skeleton-line--medium"></div>
        <div class="skeleton-line skeleton-line--long"></div>
      </div>
    </div>
  </div>

  <!-- Email cards -->
  <div class="email-list__body" *ngIf="!isLoading">
    <ng-container *ngIf="filteredEmails.length > 0; else emptyState">
      <app-email-card
        *ngFor="let email of filteredEmails; trackBy: trackById"
        [email]="email"
        [isSelected]="selectedEmail?.id === email.id"
        (selected)="selectEmail($event)"
        (starred)="toggleStar($event)">
      </app-email-card>
    </ng-container>

    <ng-template #emptyState>
      <div class="email-list__empty">
        <svg width="48" height="48" viewBox="0 0 48 48" fill="none">
          <rect x="6" y="10" width="36" height="28" rx="4" stroke="currentColor" stroke-width="1.5" stroke-opacity="0.3"/>
          <path d="M6 18l18 12 18-12" stroke="currentColor" stroke-width="1.5" stroke-opacity="0.3"/>
        </svg>
        <p *ngIf="searchQuery">No results for "{{ searchQuery }}"</p>
        <p *ngIf="!searchQuery">{{ folderTitle }} is empty</p>
      </div>
    </ng-template>
  </div>
</div>
